"""
leverage_ranker.py — Ranks dimensions by leverage: how much fixing one unlocks others.
Pure LOCAL computation, zero LLM calls.
"""

from dataclasses import dataclass, field


@dataclass
class RankedDimension:
    name: str
    leverage_score: float      # how much this unlocks other dimensions
    gap_size: float            # 1.0 - current_score
    unlocks: list[str]
    blocked_by: list[str]


class LeverageRanker:
    CAUSAL_GRAPH: dict[str, dict] = {
        "network_access": {
            "unlocks": ["capital_requirements", "deal_skills", "founder_experience"],
            "blocked_by": [],
        },
        "deal_skills": {
            "unlocks": ["capital_requirements", "execution_distance"],
            "blocked_by": ["network_access"],
        },
        "founder_experience": {
            "unlocks": ["network_access", "deal_skills", "moat_patterns"],
            "blocked_by": [],
        },
        "capital_requirements": {
            "unlocks": ["timing_windows"],
            "blocked_by": ["network_access", "deal_skills"],
        },
        "timing_windows": {
            "unlocks": [],
            "blocked_by": [],
        },
        "execution_distance": {
            "unlocks": ["timing_windows", "capital_requirements"],
            "blocked_by": ["deal_skills"],
        },
        "competitive_landscape": {
            "unlocks": ["moat_patterns"],
            "blocked_by": [],
        },
        "moat_patterns": {
            "unlocks": ["compounding_mechanisms"],
            "blocked_by": ["competitive_landscape"],
        },
        "compounding_mechanisms": {
            "unlocks": [],
            "blocked_by": ["moat_patterns"],
        },
        "base_rates": {
            "unlocks": [],
            "blocked_by": [],
        },
        "unit_economics": {
            "unlocks": ["capital_requirements"],
            "blocked_by": [],
        },
    }

    def rank(self, dimension_scores: dict) -> list[RankedDimension]:
        """
        Rank dimensions by leverage score.

        leverage_score = (gap_size * unlock_count) / max(blockers_unresolved, 1)

        Parameters
        ----------
        dimension_scores : dict
            Maps dimension name → DimensionScore or float score value.

        Returns
        -------
        list[RankedDimension] sorted by leverage_score descending.
        """
        def _score_val(dim: str) -> float:
            raw = dimension_scores.get(dim)
            if raw is None:
                return 0.0
            if isinstance(raw, (int, float)):
                return float(raw)
            # DimensionScore dataclass
            return float(raw.score)

        results: list[RankedDimension] = []

        for dim, meta in self.CAUSAL_GRAPH.items():
            current_score = _score_val(dim)
            gap_size = 1.0 - current_score
            unlocks = meta["unlocks"]
            blocked_by = meta["blocked_by"]

            unlock_count = len(unlocks)
            blockers_unresolved = sum(
                1 for b in blocked_by if (1.0 - _score_val(b)) > 0.5
            )
            leverage_score = (gap_size * unlock_count) / max(blockers_unresolved, 1)

            results.append(RankedDimension(
                name=dim,
                leverage_score=round(leverage_score, 4),
                gap_size=round(gap_size, 4),
                unlocks=list(unlocks),
                blocked_by=list(blocked_by),
            ))

        results.sort(key=lambda r: r.leverage_score, reverse=True)
        return results

