_SMALL_GAP_THRESHOLD = 0.5


class MilestoneGenerator:
    def generate(
        self,
        steps: list[StrategyStep],
        dimension_scores: dict,
    ) -> list[Milestone]:
        """
        Generate one Milestone per StrategyStep.

        Selects "small" template if gap < 0.5, "large" if gap >= 0.5.

        Parameters
        ----------
        steps : list[StrategyStep]
            Ordered steps from SequenceOptimizer.
        dimension_scores : dict
            Maps dimension name → DimensionScore or float.

        Returns
        -------
        list[Milestone] in same order as steps.
        """
        milestones: list[Milestone] = []

        for step in steps:
            dim = step.dimension
            raw = dimension_scores.get(dim)
            if raw is None:
                current_score = 0.0
            elif isinstance(raw, (int, float)):
                current_score = float(raw)
            else:
                current_score = float(raw.score)

            gap_size = round(1.0 - current_score, 4)
            size_key = "large" if gap_size >= _SMALL_GAP_THRESHOLD else "small"

            template = MILESTONE_TEMPLATES.get(dim, {}).get(size_key)
            if template:
                description = template["description"]
                metric = template["metric"]
                target_value = template["target_value"]
            else:
                description = f"Improve {dim} to acceptable level"
                metric = f"{dim}_score"
                target_value = "0.7"

            milestones.append(Milestone(
                dimension=dim,
                description=description,
                metric=metric,
                target_value=target_value,
                gap_size=gap_size,
            ))

        return milestones
